blocks.code:
data "zia_cloud_app_control_rule_actions" "deny_ai_ml_actions" {
    type = "AI_ML"
    cloud_apps = ["AI_ML_WEB_USE"]
    action_prefixes = ["DENY"]
}

resource "zia_cloud_app_control_rule" "app_control_rule_block_high_risk_ai" {
  name                    = "BLOCK_HIGH_RISK_AI"
  description             = local.policy_description
  type                    = "AI_ML"
  order                   = 1
  rank                    = 7
  state                   = "ENABLED"
  browser_eun_template_id = 8507

  actions = data.zia_cloud_app_control_rule_actions.deny_ai_ml_actions.filtered_actions

  cloud_app_risk_profile {
    id = data.zia_risk_profiles.high_risk_app_profile.id
  }
}

+ resource "zia_cloud_app_control_rule" "app_control_rule_block_high_risk_ai" {
    + id      = (known after apply)
    + name    = "BLOCK_HIGH_RISK_AI"
    + order   = 1
    + rank    = 7
    + rule_id = (known after apply)
    + state   = "ENABLED"
    + type    = "AI_ML"
    + cloud_app_risk_profile {
        + id = 1767
      }
  }
